async def test_api_chat_channel_on_message_added_delivers_contract_valid_payloads(rig):
    client, socket = rig
    await client.register_scenario(
        {
            "topic": "api:chat:team:test-id:thread:test-id",
            "onJoin": [
                {"type": "autoReply"},
                {"type": "autoPush", "event": "message_added"},
            ],
        }
    )
    channel = await ApiChatChannel.join_team_thread(
        socket,
        "test-id",
        "test-id",
        after_cursor="test-value",
        before_cursor="test-value",
        include_metadata=True,
        limit=1,
    )
    future: asyncio.Future = asyncio.get_event_loop().create_future()

    def handler(payload):
        if not future.done():
            future.set_result(payload)

    channel.on_message_added(handler)
    payload = await asyncio.wait_for(future, timeout=1.0)
    assert payload is not None


